import{_ as a,o,c as i,a2 as r}from"./chunks/framework.CnJ-JtFX.js";const m=JSON.parse('{"title":"EP.06 自定义组件不是逃离 Schema 的后门","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.06-formily-advanced.md","filePath":"comics/EP.06-formily-advanced.md","lastUpdated":1792683644000}'),s={name:"comics/EP.06-formily-advanced.md"};function c(t,e,d,n,l,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-06-自定义组件不是逃离-schema-的后门" tabindex="-1">EP.06 自定义组件不是逃离 Schema 的后门 <a class="header-anchor" href="#ep-06-自定义组件不是逃离-schema-的后门" aria-label="Permalink to &quot;EP.06 自定义组件不是逃离 Schema 的后门&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/06-formily-advanced">guide/06-formily-advanced</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君遇到 Schema 写不出的金额输入框，第一反应是整页改回 JSX；码叔拦住他，因为这一页改回去，后面所有页面都会跟着改回去。</li><li><strong>揭秘</strong>：解决方案是注册表 + 字符串名：组件实现留在代码里，用 <code>connect + mapProps</code> 接入字段状态，Schema 里只写 <code>MoneyInput</code>。</li><li><strong>实证</strong>：像素酱把布局与复用也写进配置：<code>gridSpan</code> 控制占列，对象展开复用公共字段片段。</li><li><strong>结案</strong>：码叔用实时 JSON 编辑器划出底线：能序列化、能存库、能跨端的才叫配置；塞函数的 JSON 只是换了写法的代码。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-什么时候真的需要自定义组件" tabindex="-1">第一格：什么时候真的需要自定义组件 <a class="header-anchor" href="#第一格-什么时候真的需要自定义组件" aria-label="Permalink to &quot;第一格：什么时候真的需要自定义组件&quot;">​</a></h3><p>不是所有「Schema 写不出来」都需要自定义组件。先判断三件事：内置组件能不能通过 <code>x-component-props</code> 满足；能不能用 reactions 组合已有字段；只有确认需要新的交互或格式化逻辑时，才写组件。</p><p>金额输入框需要 ¥ 前缀、两位小数、<code>null</code> 转 <code>0</code>，这些用内置 <code>NumberPicker</code> 加 props 也能接近，但公司统一组件还包含格式化与业务校验。此时自定义组件是合理的；如果只是改个 placeholder，就不值得新增一个注册项。</p><h3 id="第二格-connect-与-mapprops-的边界" tabindex="-1">第二格：connect 与 mapProps 的边界 <a class="header-anchor" href="#第二格-connect-与-mapprops-的边界" aria-label="Permalink to &quot;第二格：connect 与 mapProps 的边界&quot;">​</a></h3><p><code>connect</code> 把组件包成 observer，让字段变化时只重渲染这个组件。<code>mapProps</code> 声明哪些字段状态变成 props：</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mapProps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ value: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, onChange: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, disabled: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>只映射需要的状态，不把整个 <code>field</code> 透传给第三方组件。否则组件可能绕过模型直接改状态，联动、校验、提交都会失控。只读字段只映射 <code>value</code>，不需要 <code>onChange</code>，但它仍然是表单字段，仍然参与取值与提交。</p><h3 id="第三格-布局与复用" tabindex="-1">第三格：布局与复用 <a class="header-anchor" href="#第三格-布局与复用" aria-label="Permalink to &quot;第三格：布局与复用&quot;">​</a></h3><p><code>FormGrid</code> 提供栅格上下文，<code>FormItem</code> 读取 <code>x-decorator-props.gridSpan</code> 决定占几列。把布局写进 Schema 后，同一份字段配置换个 <code>maxColumns</code> 就能重排，不需要改每个字段的样式。</p><p>Schema 复用用对象展开：把公共片段抽成对象，再展开进页面 Schema。它做的是浅合并，优点是零依赖、可读、可测试；边界是字段级覆盖之后会变成两份独立配置，后续仍可能漂移。需要参数化时抽函数，但要接受失去可序列化。</p><h3 id="第四格-为什么实时编辑器只收纯-json" tabindex="-1">第四格：为什么实时编辑器只收纯 JSON <a class="header-anchor" href="#第四格-为什么实时编辑器只收纯-json" aria-label="Permalink to &quot;第四格：为什么实时编辑器只收纯 JSON&quot;">​</a></h3><p>实时编辑器的流程只有三步：<code>JSON.parse</code> 文本、校验根节点是 <code>type: &quot;object&quot;</code>、交给同一个 <code>SchemaField</code> 渲染。它故意不接受函数，因为一旦 Schema 里有函数，文本就无法解析，配置无法存库，跨端也无法执行。</p><p>这条限制不是技术洁癖，而是产品边界：低代码平台的配置必须能被存储、传输、diff、回滚。需要函数的逻辑应该放在自定义组件、函数式 reactions 或后端规则引擎里，而不是塞进配置文本。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>只 <code>connect</code> 不 <code>mapProps</code></strong>：组件拿不到 <code>value/onChange</code>，表现是「能看不能改」。</li><li><strong>把整个 field 透传给第三方组件</strong>：组件可能绕过模型改状态，联动与校验失控。</li><li><strong>把只读展示写成纯 UI</strong>：值不进模型，提交时还得再算一遍。</li><li><strong><code>gridSpan</code> 写到 <code>x-component-props</code></strong>：FormItem 读的是 <code>x-decorator-props</code>，写错不生效。</li><li><strong>实时编辑器不捕获解析异常</strong>：一个坏字符就让页面白屏。</li><li><strong>Schema 里塞函数或正则字面量</strong>：无法序列化，存库与跨端都会失败。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 自定义字段为什么要在 Schema 里写字符串名，而不是组件对象？</b></summary><p>因为 Schema 需要被序列化、存库、跨端传输和做版本 diff。组件对象包含函数与运行时依赖，无法被 JSON 表达。字符串名 + 注册表把配置与实现分离，组件升级不影响历史配置。</p></details><details><summary><b>2. 只读展示字段为什么也要用 connect 接入模型？</b></summary><p>因为它需要参与取值、校验、联动和提交。写成纯 UI 组件后，值只存在于视图层，提交时拿不到，只能在提交函数里重算，规则又散了一处。用 <code>mapProps({ value: true })</code> 保留字段身份即可。</p></details><details><summary><b>3. 实时编辑器为什么不允许在 JSON 里写校验函数？</b></summary><p>因为函数无法被 <code>JSON.parse</code>，配置也就无法存库、跨端和 diff。需要函数的场景应放到代码里的自定义组件、函数式 reactions 或后端规则引擎，配置文本只保留可序列化的结构。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/06-formily-advanced">第 06 章正文</a></li><li><a href="./../guide/05-formily-linkage">第 05 章 · 联动与异步校验</a></li><li><a href="./../guide/07-lowcode-engine-architecture">第 07 章 · lowcode-engine 架构</a></li></ul>',26)])])}const u=a(s,[["render",c]]);export{m as __pageData,u as default};
